// Erst der Selektor, dann die KI: ein Token pro Seite und Tag summiert sich, und
// ein funktionierender Selektor ist praeziser als jedes Modell. Die KI ist der
// Rueckfall fuer Shops, die ihr Markup aendern oder den Preis verschachteln.

function alsBetrag(text) {
  const s = String(text ?? '').replace(/[^0-9,.]/g, '');
  if (!s) return null;
  // Deutsches Format (1.299,00) vom englischen (1,299.00) unterscheiden: massgeblich
  // ist, welches Zeichen zuletzt steht - das ist das Dezimaltrennzeichen.
  const letzterPunkt = s.lastIndexOf('.');
  const letztesKomma = s.lastIndexOf(',');
  let normalisiert;
  if (letztesKomma > letzterPunkt) {
    normalisiert = s.replace(/\./g, '').replace(',', '.');
  } else {
    normalisiert = s.replace(/,/g, '');
  }
  const zahl = Number(normalisiert);
  return isFinite(zahl) && zahl > 0 ? Number(zahl.toFixed(2)) : null;
}

function tagsRaus(html) {
  return String(html).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
}

// Bewusst regexbasierte Auswertung statt echter DOM-Navigation: cheerio ist im
// Code-Node nicht garantiert verfuegbar, und fuer "nimm den Text in dem Element
// mit dieser Klasse" reicht es. Wird das Markup komplexer, greift die KI.
function ausSelektor(html, selektor) {
  const sel = String(selektor ?? '').trim();
  if (!sel) return null;
  let treffer = null;
  if (sel.startsWith('.')) {
    const klasse = sel.slice(1).replace(/[^A-Za-z0-9_-]/g, '');
    treffer = html.match(new RegExp('class="[^"]*\\b' + klasse + '\\b[^"]*"[^>]*>([\\s\\S]{0,200}?)<', 'i'));
  } else if (sel.startsWith('#')) {
    const id = sel.slice(1).replace(/[^A-Za-z0-9_-]/g, '');
    treffer = html.match(new RegExp('id="' + id + '"[^>]*>([\\s\\S]{0,200}?)<', 'i'));
  } else if (sel.startsWith('[')) {
    const attr = sel.replace(/[\[\]"']/g, '');
    const teile = attr.split('=');
    if (teile.length === 2) {
      // Bei meta-Tags steht der Preis im content-Attribut, nicht im Text.
      const meta = html.match(new RegExp(teile[0] + '="' + teile[1] + '"[^>]*content="([^"]+)"', 'i'));
      treffer = meta || html.match(new RegExp(teile[0] + '="' + teile[1] + '"[^>]*>([\\s\\S]{0,200}?)<', 'i'));
    }
  }
  return treffer ? alsBetrag(tagsRaus(treffer[1])) : null;
}

// Zweiter Versuch ohne Selektor: strukturierte Daten. Die meisten Shops liefern
// den Preis maschinenlesbar mit, bevor man ihn aus dem Layout kratzen muss.
function ausStrukturdaten(html) {
  const meta = html.match(/itemprop="price"[^>]*content="([^"]+)"/i)
    || html.match(/property="product:price:amount"[^>]*content="([^"]+)"/i)
    || html.match(/"price"\s*:\s*"?([0-9.,]+)"?/i);
  return meta ? alsBetrag(meta[1]) : null;
}

const raus = [];

for (const eintrag of $input.all()) {
  const antwort = eintrag.json;
  const p = $('Produktliste lesen').item.json;
  const html = String(antwort.body ?? '');

  let preis = ausSelektor(html, p['Selektor']);
  let quelle = preis === null ? null : 'Selektor';
  if (preis === null) {
    preis = ausStrukturdaten(html);
    if (preis !== null) quelle = 'Strukturdaten';
  }

  // Fuer den KI-Fallback nur einen Ausschnitt mitgeben: Skripte und Styles raus,
  // auf 6000 Zeichen kuerzen. Das spart Token und haelt den Kontext sauber.
  const rumpf = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ');
  const index = rumpf.search(/preis|price|EUR|€/i);
  const start = Math.max(0, index - 2000);

  raus.push({
    json: {
      produkt: p['Produkt'] ?? '',
      artikelnummer: p['Artikelnummer'] ?? '',
      wettbewerber: p['Wettbewerber'] ?? '',
      url: p['URL'] ?? '',
      eigener_preis_roh: p['Eigener Preis'] ?? '',
      schwelle_prozent: Number(String(p['Schwelle Prozent'] ?? '3').replace(',', '.')) || 3,
      preis_wettbewerb: preis,
      preis_quelle: quelle,
      preis_gefunden: preis !== null,
      html_ausschnitt: tagsRaus(rumpf.slice(start, start + 6000)),
    },
  });
}

return raus;

// Fehlerzweig: Der Abruf ist gescheitert (Timeout, 403, Bot-Sperre, Seite weg).
// Der Datensatz bekommt trotzdem dieselbe Struktur wie ein erfolgreicher Lauf und
// wandert in die Historie. Nur so faellt beim Durchblaettern auf, wenn eine URL
// seit drei Wochen nichts mehr liefert - stilles Verschlucken faellt nie auf.

const raus = [];

for (const eintrag of $input.all()) {
  const antwort = eintrag.json;
  const p = $('Produktliste lesen').item.json;
  const status = Number(antwort.statusCode ?? 0);

  let hinweis = 'HTTP-Status ' + status;
  if (status === 403 || status === 429) {
    hinweis += ' - die Seite blockt automatisierte Abrufe. Vor weiteren Versuchen robots.txt und Nutzungsbedingungen pruefen.';
  } else if (status === 404 || status === 410) {
    hinweis += ' - Produktseite existiert nicht mehr, URL im Sheet aktualisieren.';
  } else if (status === 0) {
    hinweis = 'Keine Antwort (Timeout oder DNS-Fehler)';
  }

  raus.push({
    json: {
      produkt: p['Produkt'] ?? '',
      wettbewerber: p['Wettbewerber'] ?? '',
      url: p['URL'] ?? '',
      eigener_preis: null,
      preis_wettbewerb: null,
      abweichung_prozent: null,
      preis_quelle: 'Abruf fehlgeschlagen',
      status_text: hinweis,
      meldung_noetig: false,
    },
  });
}

return raus;

// Der Vergleich entscheidet ueber die Meldung. Zwei Dinge sind hier wichtiger als
// die Rechnung selbst: eine Plausibilitaetsgrenze, damit ein falsch gelesener
// Cent-Betrag oder ein Ratenpreis keinen Alarm ausloest, und der je Produkt
// gepflegte Schwellenwert, damit nicht jede Rundung eine Mail erzeugt.

const PLAUSIBEL_MIN_FAKTOR = 0.2;   // Wettbewerbspreis unter 20 % des eigenen: unglaubwuerdig
const PLAUSIBEL_MAX_FAKTOR = 5;     // ueber dem Fuenffachen ebenfalls

function alsBetrag(wert) {
  if (typeof wert === 'number') return wert;
  const s = String(wert ?? '').replace(/[^0-9,.\-]/g, '');
  if (!s) return 0;
  return Number(s.replace(/\./g, '').replace(',', '.')) || 0;
}

const raus = [];

for (const eintrag of $input.all()) {
  const q = eintrag.json;
  // Der Datensatz kommt entweder direkt vom Selektor-Node oder ueber die KI.
  // Im zweiten Fall enthaelt er nur das Modellergebnis, der Produktkontext wird
  // ueber den Node-Namen nachgeholt.
  const kontext = q.produkt ? q : $('Preis per Selektor lesen').item.json;
  const kiWert = q.produkt ? null : (q.preis ?? q.message?.content?.preis ?? null);

  const eigener = Number(alsBetrag(kontext.eigener_preis_roh).toFixed(2));
  const fremd = kiWert !== null && kiWert !== undefined ? Number(Number(kiWert).toFixed(2)) : kontext.preis_wettbewerb;
  const quelle = kiWert !== null && kiWert !== undefined ? 'KI' : kontext.preis_quelle;
  const schwelle = Number(kontext.schwelle_prozent ?? 3);

  let abweichung = null;
  let status = '';
  let meldung = false;

  if (!eigener) {
    status = 'Eigener Preis fehlt im Sheet - kein Vergleich moeglich';
  } else if (fremd === null || fremd === undefined) {
    status = 'Kein Preis erkannt, auch nicht per KI - Selektor pruefen';
  } else if (fremd < eigener * PLAUSIBEL_MIN_FAKTOR || fremd > eigener * PLAUSIBEL_MAX_FAKTOR) {
    status = 'Ausgelesener Preis ' + fremd.toFixed(2) + ' EUR unplausibel zum eigenen Preis - vermutlich Rate, Zubehoer oder Staffelpreis';
  } else {
    abweichung = Number((((fremd - eigener) / eigener) * 100).toFixed(1));
    meldung = Math.abs(abweichung) >= schwelle;
    if (abweichung < 0) {
      status = 'Wettbewerber ist ' + Math.abs(abweichung) + ' Prozent guenstiger';
    } else if (abweichung > 0) {
      status = 'Wettbewerber ist ' + abweichung + ' Prozent teurer';
    } else {
      status = 'Preisgleich';
    }
    if (!meldung) {
      status += ' (unter der Schwelle von ' + schwelle + ' Prozent, keine Meldung)';
    }
  }

  raus.push({
    json: {
      produkt: kontext.produkt,
      artikelnummer: kontext.artikelnummer,
      wettbewerber: kontext.wettbewerber,
      url: kontext.url,
      eigener_preis: eigener || null,
      preis_wettbewerb: fremd ?? null,
      abweichung_prozent: abweichung,
      abweichung_eur: abweichung === null ? null : Number((fremd - eigener).toFixed(2)),
      schwelle_prozent: schwelle,
      preis_quelle: quelle,
      status_text: status,
      meldung_noetig: meldung,
    },
  });
}

return raus;

